<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Untitled Document</title>
    <script src="https://cdn.jsdelivr.net/npm/mathjax@3/es5/tex-mml-chtml.js" integrity="sha384-..."></script>
    <style>
        @import url('https://fonts.googleapis.com/css2?family=Georgia:wght@400;600&amp;family=Times+New+Roman:wght@400;600&amp;display=swap');

        body {
            font-family: 'Georgia', serif;
            line-height: 1.4;
            margin: 0.75in auto;
            max-width: 8.5in;
            color: #000;
            background: #fff;
        }

        /* Heading styles (approximating bold/large) */
        h1, .heading {
            font-family: 'Times New Roman', serif;
            font-size: 28px;
            font-weight: 600;
            text-align: center;
            margin: 0.3in 0 0.2in;
            letter-spacing: 0.05em;
        }

        .subheading {
            font-family: 'Georgia', serif;
            font-size: 18px;
            font-weight: 400;
            text-align: center;
            margin: 0.1in 0 0.3in;
        }

        /* Column layout for multi-column pages */
        .columns {
            display: flex;
            gap: 0.6in;
            margin: 0.3in 0;
        }

        .column {
            flex: 1;
            display: flex;
            flex-direction: column;
            gap: 0.25in;
        }

        .column h2 {
            font-size: 22px;
            font-weight: 600;
            margin: 0 0 0.15in;
            border-bottom: 1px solid #333;
            padding-bottom: 0.05in;
        }

        p {
            margin: 0 0 0.18in;
            text-align: justify;
            font-size: 13.5px;
        }

        /* Indentation for paragraphs */
        .indent {
            text-indent: 0.3in;
            margin: 0 0 0.18in;
        }

        /* Lists */
        ul, ol {
            margin: 0 0 0.18in 0.3in;
            padding-left: 0.25in;
        }

        li {
            margin: 0.08in 0;
            font-size: 13.5px;
        }

        /* Placeholder for non-text (charts, photos, signatures, diagrams) */
        .placeholder {
            width: 100%;
            height: 3in;
            background-color: #f8f8f8;
            border: 1px solid #ddd;
            margin: 0.25in 0;
            display: flex;
            align-items: center;
            justify-content: center;
            font-family: Georgia, serif;
            font-size: 14px;
            color: #666;
            text-align: center;
            position: relative;
        }

        .placeholder::before {
            content: attr(data-caption);
            font-style: italic;
        }

        /* Signature / line placeholder */
        .signature {
            width: 2.5in;
            height: 0.6in;
            border-bottom: 1px solid #000;
            margin: 0.4in 0;
            position: relative;
        }

        /* Table placeholder */
        .table {
            width: 100%;
            border: 1px solid #000;
            border-collapse: collapse;
            margin: 0.3in 0;
            font-size: 12px;
        }

        .table th, .table td {
            border: 1px solid #000;
            padding: 0.08in 0.15in;
            text-align: left;
        }

        /* Footer / page number */
        .footer {
            margin-top: 0.5in;
            text-align: center;
            font-size: 11px;
            color: #555;
        }

        /* Bold text simulation */
        strong, b {
            font-weight: 600;
        }

        /* Underline simulation */
        u {
            text-decoration: underline;
        }
    </style>
</head>
<body>

    <!-- Top margin placeholder -->
    <div style="height:0.5in;"></div>

    <!-- Example header / title block -->
    <div class="heading">Document Title</div>
    <div class="subheading">Subtitle or Author Name</div>

    <p class="indent">First paragraph of the document. All text is extracted verbatim from the image. This is an example of how the HTML will look when the actual document content is provided.</p>

    <!-- Placeholder for image or diagram -->
    <div class="placeholder" data-caption="[Image: Centered illustration or photograph at top of page]" style="width:6.5in;height:2.2in;margin:0.3in auto;"></div>

    <h2>Section Heading</h2>

    <div class="columns">
        <!-- Column 1 -->
        <div class="column">
            <p class="indent">Text in the left column. This simulates a multi-column newspaper or flyer layout.</p>
            <p class="indent">More text continues here with proper line spacing.</p>
            <ul>
                <li>Bullet point 1</li>
                <li>Bullet point 2</li>
            </ul>
        </div>

        <!-- Column 2 -->
        <div class="column">
            <p class="indent">Text in the right column. Side-by-side with the left column.</p>
            <p class="indent">Additional content aligned to match original spacing.</p>
            <ol>
                <li>Numbered item 1</li>
                <li>Numbered item 2</li>
            </ol>
        </div>
    </div>

    <!-- Signature line -->
    <div class="signature" style="margin:0.6in 0;"></div>

    <!-- Placeholder for table -->
    <div class="placeholder" data-caption="[Table: 3-column table with merged cells]" style="width:6.5in;height:1.8in;"></div>

    <p><strong>Bold text</strong> and <u>underlined text</u> are preserved where present in the original image.</p>

    <div class="footer">
        Page 1 • Footer text if present
    </div>

</body>
</html>
